package com.ellenco.platform.controllers;import com.ellenco.platform.auth.User;import com.ellenco.platform.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;
@RestController@RequestMapping("/api/tools")@PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')")public class ToolController{private final ToolAssetRepository tools;private final ToolLoanRepository loans;private final WarehouseRepository warehouses;private final AuditService audit;public ToolController(ToolAssetRepository t,ToolLoanRepository l,WarehouseRepository w,AuditService a){tools=t;loans=l;warehouses=w;audit=a;}@GetMapping public List<ToolAsset> list(){return tools.findAll();}@PostMapping@Transactional public ToolAsset create(@RequestBody ToolAsset t,@RequestParam(required=false)Long galpaoId,@AuthenticationPrincipal User u){if(tools.existsByPatrimonio(t.getPatrimonio()))throw new IllegalArgumentException("Patrimônio já cadastrado.");if(galpaoId!=null)t.setGalpao(warehouses.findById(galpaoId).orElseThrow(()->new IllegalArgumentException("Almoxarifado não encontrado.")));ToolAsset s=tools.save(t);audit.log(u.getNome(),u.getEmail(),"FERRAMENTAS","CADASTRO","ToolAsset",s.getId().toString(),s.getPatrimonio()+" · "+s.getNome());return s;}@GetMapping("/loans")public List<ToolLoan> history(){return loans.findAllByOrderByEmprestadoEmDesc();}@PostMapping("/{id}/loan")@Transactional public ToolLoan loan(@PathVariable Long id,@RequestBody ToolLoan l,@AuthenticationPrincipal User u){ToolAsset t=tools.findById(id).orElseThrow(()->new IllegalArgumentException("Ferramenta não encontrada."));if(!"DISPONIVEL".equals(t.getStatus()))throw new IllegalArgumentException("Ferramenta indisponível: "+t.getStatus());l.setFerramenta(t);l.setEstadoSaida(t.getEstadoConservacao());l.setStatus("EMPRESTADO");l.setComprovanteCodigo("FER-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());t.setStatus("EMPRESTADO");tools.save(t);ToolLoan s=loans.save(l);audit.log(u.getNome(),u.getEmail(),"FERRAMENTAS","EMPRESTIMO","ToolLoan",s.getId().toString(),s.getComprovanteCodigo()+" para "+s.getResponsavelNome());return s;}@PostMapping("/loans/{id}/return")@Transactional public ToolLoan giveBack(@PathVariable Long id,@RequestBody Map<String,String>b,@AuthenticationPrincipal User u){ToolLoan l=loans.findById(id).orElseThrow(()->new IllegalArgumentException("Empréstimo não encontrado."));if(!"EMPRESTADO".equals(l.getStatus()))throw new IllegalArgumentException("Empréstimo já encerrado.");String state=b.getOrDefault("estadoDevolucao","BOM");l.setEstadoDevolucao(state);l.setObservacoes(b.get("observacoes"));l.setDevolvidoEm(LocalDateTime.now());l.setStatus("DEVOLVIDO");ToolAsset t=l.getFerramenta();t.setEstadoConservacao(state);t.setStatus(List.of("AVARIADO","DANIFICADO").contains(state)?"MANUTENCAO":"DISPONIVEL");tools.save(t);audit.log(u.getNome(),u.getEmail(),"FERRAMENTAS","DEVOLUCAO","ToolLoan",id.toString(),"Estado: "+state);return loans.save(l);}}
